insert into checklist_items (program_id, phase, days_offset, sort_order, title_ko, body_ko, source_id, verified_at, needs_review) values
  (null, 'decide', -180, 0, '여권 유효기간 확인', '남은 기간이 체류 기간 + 6개월 이상인지 봐요. 모자라면 새로 만들어요(구청·시청, 보통 1~2주).', null, '2026-11-11', false),
  (null, 'decide', -180, 10, '갈 나라의 접수 일정과 조건 확인', '나이, 선발 방식, 다음 접수일을 나라 상세에서 확인해요.', null, '2026-11-11', false),
  (null, 'decide', -150, 20, '예산 정하기', '잔고 증명 + 항공권 + 첫 달 집세와 생활비를 더해 목표 금액을 정해요.', null, '2026-11-11', false),
  (null, 'decide', -120, 30, '(남성) 병역 국외여행허가 확인', '병역을 마치지 않은 만 25세 이상 남성은 출국 전에 병무청 국외여행허가를 받아야 해요.', null, '2026-11-11', true),
  (null, 'apply', -120, 40, '잔고 증명용 돈 준비', '나라마다 정한 금액을 본인 이름 계좌에 넣어 둬요. 일정 기간 유지해야 하는 나라도 있어요.', null, '2026-11-11', false),
  (null, 'apply', -100, 50, '영문 이력서 만들기', '비자 신청과 현지 구직에 같이 써요. 일본은 일본어 또는 영어.', null, '2026-11-11', false),
  (null, 'apply', -90, 60, '비자 신청하기', '아래 "필요한 서류"를 모두 준비해서 신청해요.', null, '2026-11-11', false),
  (null, 'apply', -60, 70, '비자 승인서 저장·인쇄', '승인 메일과 승인서를 휴대폰과 클라우드에 저장하고, 종이로도 1부 챙겨요.', null, '2026-11-11', false),
  (null, 'prepare', -60, 80, '항공권 예약', '입국 때 귀국·다음 항공권이나 살 돈을 확인하는 나라가 있어요.', null, '2026-11-11', false),
  (null, 'prepare', -45, 90, '해외 체류 보험 가입', '체류 전 기간을 보장하는지, 나라가 요구하는 보장 범위를 만족하는지 확인해요.', null, '2026-11-11', false),
  (null, 'prepare', -30, 100, '첫 숙소 2~4주 예약', '도착 직후 머물 곳을 정해 두면 주소가 필요한 등록 절차가 쉬워져요.', null, '2026-11-11', false),
  (null, 'prepare', -30, 110, '국제운전면허증 발급', '운전면허시험장이나 경찰서에서 바로 발급돼요. 유효기간은 1년이에요.', null, '2026-11-11', false),
  (null, 'prepare', -30, 120, '치과·건강 점검, 상비약 준비', '해외 치과 치료는 비싸요. 복용 중인 약은 영문 처방전과 같이 챙겨요.', null, '2026-11-11', false),
  (null, 'prepare', -30, 130, '해외 결제 카드 준비', '해외 결제 수수료가 낮은 체크카드·신용카드를 1~2장 준비해요.', null, '2026-11-11', false),
  (null, 'prepare', -21, 140, '해외 송금 방법 정하기', '잔고 이체, 현지 계좌 입금에 쓸 송금 서비스를 미리 가입해 둬요.', null, '2026-11-11', false),
  (null, 'prepare', -14, 150, '건강보험·국민연금 확인', '공단에 출국 기간을 알리고 보험료 면제·납부예외가 되는지 확인해요.', null, '2026-11-11', true),
  (null, 'prepare', -14, 160, '한국 휴대폰 번호 정하기', '장기 일시정지나 저렴한 요금제로 번호를 유지하면 본인인증을 계속 쓸 수 있어요.', null, '2026-11-11', false),
  (null, 'prepare', -14, 170, '중요 서류 사본 저장', '여권·비자 승인서·보험증서·잔고증명 사본을 클라우드에 올려 둬요.', null, '2026-11-11', false),
  (null, 'depart', -7, 180, '짐 싸기', '멀티 어댑터, 상비약, 계절 옷, 서류 파일을 챙겨요.', null, '2026-11-11', false),
  (null, 'depart', -7, 190, '해외안전여행 앱 설치, 영사콜센터 번호 저장', '영사콜센터 +82-2-3210-0404. 현지 대사관 연락처도 저장해요.', null, '2026-11-11', false),
  (null, 'depart', -3, 200, '입국 서류 한 파일에 모으기', '비자 승인서, 잔고증명, 보험증서, 항공권, 첫 숙소 주소를 출력해서 기내 가방에 넣어요.', null, '2026-11-11', false),
  (null, 'depart', -3, 210, '현지 돈 조금 환전', '첫날 교통비와 식비 정도만 현금으로 준비해요.', null, '2026-11-11', false),
  (null, 'arrive', 1, 220, '현지 유심·eSIM 개통', '현지 번호가 있어야 은행·집·일자리 연락이 쉬워요.', null, '2026-11-11', false),
  (null, 'arrive', 7, 230, '은행 계좌 만들기', '급여를 받으려면 현지 계좌가 필요해요.', null, '2026-11-11', false),
  (null, 'arrive', 7, 240, '일자리 찾기 시작', '이력서를 현지 형식으로 고치고 구인 사이트에 올려요.', null, '2026-11-11', false),
  (null, 'arrive', 14, 250, '장기 숙소 구하기', '계약 전에 집을 직접 보고, 보증금 조건을 글로 받아 둬요.', null, '2026-11-11', false),
  (null, 'arrive', 30, 260, '재외국민등록', '외국에서 90일 넘게 지내면 관할 대사관·총영사관에 등록해야 해요(영사민원24).', null, '2026-11-11', false),
  ((select id from programs where origin='KR' and destination='AU' and kind='working_holiday'), 'arrive', 7, 270, '세금번호(TFN) 신청', '일을 시작하기 전에 신청해요. 없으면 세금을 더 많이 떼요.', null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='AU' and kind='working_holiday'), 'arrive', 14, 280, '퇴직연금(Super) 계좌 확인', '고용주가 넣어 주는 Super는 귀국 후 돌려받을 수 있어요. 계좌 정보를 잘 보관해요.', null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='AU' and kind='working_holiday'), 'during', 30, 290, '(세컨비자 원하면) 지정 지역 근무 기록 남기기', '급여명세서와 근무 기록을 모두 보관해요. 지정 지역 여부는 우편번호로 확인해요.', null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 'arrive', 0, 300, '공항에서 재류카드 받기', '입국 심사 때 재류카드를 받아요. 잃어버리지 않게 보관해요.', (select id from sources where url = 'https://japan-visa.com/ko/visas/working-holiday'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 'arrive', 14, 310, '구청에 주소 신고', '주소를 정하면 14일 안에 구청(시청)에 전입 신고를 해요.', null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 'arrive', 14, 320, '국민건강보험 가입', '주소 신고 때 구청에서 같이 가입해요.', null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='CA' and kind='working_holiday'), 'depart', -3, 330, '입국 서류 확인 (POE 레터·잔고·보험)', '공항에서 이 서류를 보고 워크퍼밋을 발급해요. 잔고증명은 출국 1주 안에 뗀 것을 준비해요.', (select id from sources where url = 'https://moving2canada.com/documents-iec-work-permit-application/'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='CA' and kind='working_holiday'), 'arrive', 0, 340, '워크퍼밋 정보 확인', '공항에서 받은 퍼밋의 이름·기간이 맞는지, 보험 기간보다 짧게 나오지 않았는지 그 자리에서 확인해요.', (select id from sources where url = 'https://moving2canada.com/documents-iec-work-permit-application/'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='CA' and kind='working_holiday'), 'arrive', 7, 350, '사회보험번호(SIN) 신청', '일하려면 필요해요. Service Canada에서 신청해요.', null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='GB' and kind='working_holiday'), 'depart', -7, 360, 'UKVI 계정에서 eVisa 확인', '여권 정보가 eVisa에 연결돼 있는지 확인해요.', (select id from sources where url = 'https://tnaqa.mirrorweb.com/ukgwa/20260806184153mp_/https://www.gov.uk/youth-mobility/print'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='GB' and kind='working_holiday'), 'arrive', 14, 370, '국민보험번호(NI number) 신청', '일하려면 필요해요. 온라인으로 신청해요.', null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='GB' and kind='working_holiday'), 'arrive', 30, 380, 'GP(동네 병원) 등록', '건강부담금(IHS)을 냈으면 NHS 진료를 받을 수 있어요. 가까운 GP에 등록해요.', (select id from sources where url = 'https://tnaqa.mirrorweb.com/ukgwa/20260806184153mp_/https://www.gov.uk/youth-mobility/print'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='NZ' and kind='working_holiday'), 'prepare', -45, 390, '체류 전 기간 보험 가입', '뉴질랜드 워홀은 체류 기간 내내 의료·여행자 보험이 있어야 해요.', null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='NZ' and kind='working_holiday'), 'arrive', 7, 400, '세금번호(IRD number) 신청', '일을 시작하기 전에 신청해요.', null, '2026-11-11', true);
insert into required_documents (program_id, sort_order, title_ko, body_ko, issuer, max_age_days, translation_required, apostille_required, source_id, verified_at, needs_review) values
  ((select id from programs where origin='KR' and destination='AU' and kind='working_holiday'), 10, '여권', '체류 기간 내내 유효해야 해요.', '외교부(구청·시청)', null, false, false, (select id from sources where url = 'https://blog.orbitremit.com/working-holiday-australia-south-korea/'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='AU' and kind='working_holiday'), 20, '영문 잔고증명서', '약 AUD 5,000 + 귀국 항공권 살 돈. 신청·입국 때 요청받을 수 있어요.', '은행', null, false, false, (select id from sources where url = 'https://blog.orbitremit.com/working-holiday-australia-south-korea/'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='AU' and kind='working_holiday'), 30, '영문 범죄경력회보서', '요청받으면 제출해요.', '경찰청', null, false, false, (select id from sources where url = 'https://blog.orbitremit.com/working-holiday-australia-south-korea/'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='AU' and kind='working_holiday'), 40, '신체검사', '요청받은 경우에만 지정 병원에서 받아요.', '지정 병원', null, false, false, null, '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 10, '사증 신청서', '정해진 양식, 사진 붙임.', '대리신청기관', null, false, false, (select id from sources where url = 'https://www.themoin.com/blog/2026%EB%85%84-2%EB%B6%84%EA%B8%B0-%EC%9D%BC%EB%B3%B8-%EC%9B%8C%ED%82%B9%ED%99%80%EB%A6%AC%EB%8D%B0%EC%9D%B4-%EC%8B%A0%EC%B2%AD-%EB%B0%A9%EB%B2%95-%EC%99%84%EB%B2%BD-%EA%B0%80%EC%9D%B4%EB%93%9C/'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 20, '이력서', '일본어 또는 영어.', '본인 작성', null, false, false, (select id from sources where url = 'https://www.themoin.com/blog/2026%EB%85%84-2%EB%B6%84%EA%B8%B0-%EC%9D%BC%EB%B3%B8-%EC%9B%8C%ED%82%B9%ED%99%80%EB%A6%AC%EB%8D%B0%EC%9D%B4-%EC%8B%A0%EC%B2%AD-%EB%B0%A9%EB%B2%95-%EC%99%84%EB%B2%BD-%EA%B0%80%EC%9D%B4%EB%93%9C/'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 30, '이유서(조사표)', '왜 워홀을 가는지. A4 1장 이상, 일본어 또는 영어.', '본인 작성', null, false, false, (select id from sources where url = 'https://whic.mofa.go.kr/whic/notice/board_view.jsp?idx=16579'), '2026-11-11', false),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 40, '활동 계획서', '일본에서 무엇을 할지. A4 1장 이상, 일본어 또는 영어.', '본인 작성', null, false, false, (select id from sources where url = 'https://whic.mofa.go.kr/whic/notice/board_view.jsp?idx=16579'), '2026-11-11', false),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 50, '기본증명서 (상세)', null, '정부24·주민센터', null, false, false, (select id from sources where url = 'https://www.themoin.com/blog/2026%EB%85%84-2%EB%B6%84%EA%B8%B0-%EC%9D%BC%EB%B3%B8-%EC%9B%8C%ED%82%B9%ED%99%80%EB%A6%AC%EB%8D%B0%EC%9D%B4-%EC%8B%A0%EC%B2%AD-%EB%B0%A9%EB%B2%95-%EC%99%84%EB%B2%BD-%EA%B0%80%EC%9D%B4%EB%93%9C/'), '2026-11-11', true),
  ((select id from programs where origin='KR' and destination='JP' and kind='working_holiday'), 60, '주민등록초본', '등본도 가능.', '정부24·주민센터', null, false, false, (select id from sources where url = 'https://www.themoin.com/blog/2026%EB%85%84-2%EB%B6%84%EA%B8%B0-%EC%9D%BC%EB%B3%B8-%EC%9B%8C%ED%82%B9%ED%99%80%EB%A6%AC%EB%8D%B0%EC%9D%B4-%EC%8B%A0%EC%B2%AD-%EB%B0%A9%EB%B2%95-%EC%99%84%EB%B2%BD-%EA%B0%80%EC%9D%B4%EB%93%9C/'), '2026-11-11', true),
